// Функция для поиска наиболее надежного пути
double findMostReliablePath(const vector<vector<Edge>>& graph, int source, int destination) {
    int n = graph.size();
    vector<double> reliability(n, 0.0); // Массив для хранения наиболее надежных путей до каждой вершины
    reliability[source] = 1.0; // Надежность источника равна 1

    queue<int> q;
    q.push(source);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (const Edge& edge : graph[u]) {
            int v = edge.to;
            double edgeReliability = edge.reliability;

            if (reliability[u] * edgeReliability > reliability[v]) {
                reliability[v] = reliability[u] * edgeReliability;
                q.push(v);
            }
        }
    }

    return reliability[destination];
}

