using namespace std;

int binarySearch(vector<string> lista, string item) { // Функция бинарного поиска
    if (lista[0] == item) { // Проверяем совпадение элемента с первым в списке и возвращаем его индекс, если есть совпадение
        return 0;
    }
    int low = -1; // Это новая нижняя граница поиска
    int high = lista.size() - 1; // Верхняя граница - длина (кол-во элементов) списка минус 1
    while (low <= high) { // Запускаем цикл бинарного поиска до тех пор, пока нижняя граница меньше или равна верхней
        int mid = (low + high) / 2; // Определяем средний индекс списка
        if (lista[mid] == item) { // Если нашли совпадение, возвращаем его индекс
            return mid;
        } else if (lista[mid] < item) { // Если элемент находится выше среднего значения, устанавливаем нижнюю границу бинарного поиска
            low = mid + 1;
        } else { // Если элемент находится ниже среднего значения, устанавливаем верхнюю границу бинарного поиска
            high = mid - 1;
        }
    }
    return -1; // Если элемент не найден в списке, возвращаем -1
}

