class ZYLLockFreeQueue {
public:
    ZYLLockFreeQueue();
    ~ZYLLockFreeQueue();

    bool Enqueue(const RTPPacket& value);
    bool Dequeue(RTPPacket& value);
    size_t size() const;

private:
    struct Node {
        RTPPacket packet;
        std::atomic<Node*> next;
    };

    std::atomic<Node*> head;
    std::atomic<Node*> tail;
    std::atomic<size_t> count;
};

// ZYLLockFreeQueue.cpp
#include “ZYLLockFreeQueue.h”

ZYLLockFreeQueue::ZYLLockFreeQueue() {
    Node* dummy = new Node;
    dummy->next.store(nullptr);
    head.store(dummy);
    tail.store(dummy);
    count.store(0);
}

ZYLLockFreeQueue::~ZYLLockFreeQueue() {
    while (head.load() != tail.load()) {
        Node* temp = head.load();
        head.store(head.load()->next.load());
        delete temp;
    }
    delete head.load();
}

bool ZYLLockFreeQueue::Enqueue(const RTPPacket& value) {
    Node* newNode = new Node;
    newNode->packet = value;
    newNode->next.store(nullptr);

    Node* curTail;
    do {
        curTail = tail.load();
    } while (!std::atomic_compare_exchange_weak(&tail, &curTail, newNode));
    curTail->next.store(newNode);
    count.fetch_add(1);
    return true;
}

bool ZYLLockFreeQueue::Dequeue(RTPPacket& value) {
    Node* curHead;
    Node* nextHead;
    do {
        curHead = head.load();
        nextHead = curHead->next.load();
        if (nextHead == nullptr) {
            return false;
        }
    } while (!std::atomic_compare_exchange_weak(&head, &curHead, nextHead));
    value = nextHead->packet;
    count.fetch_sub(1);
    delete curHead;
    return true;
}

size_t ZYLLockFreeQueue::size() const {
    return count.load();
}

