#include<iostream>
#include<vector>
#include<cmath>
using namespace std;
class PageRank {
private:
    int n; // 网页数量
    double beta; // 跟随出链打开网页的概率
    double epsilon; // 精度，判断迭代是否结束
    vector<vector<double>> links; // 网页链接矩阵
    vector<double> PR; // 网页PR值
    vector<bool> zeroOutLinks; // 网页出链是否全为0的标记

    // 判断网页出链是否全为0
    void checkZeroOutLinks() {
        for (int j = 0; j < n; ++j) {
            bool flag = true;
            for (int i = 0; i < n; ++i) {
                if (links[i][j]) {
                    flag = false;
                    break;
                }
            }
            zeroOutLinks[j] = flag;
        }
    }

    //初始化PR值
    void initPR() {
        double initVal = 1.0 / n; // 初始值为1/n
        for (int i = 0; i < n; ++i) {
            PR[i] = initVal;
        }
    }

    //解决Dead Lines问题 
    void  Teleport()
    {
        checkZeroOutLinks();
        for (int j = 0; j < n; j++)
        {
            if (zeroOutLinks[j])
            {
                for (int i = 0; i < n; i++)
                {
                    links[i][j] += 1.0 / n;
                }
            }
        }
    }

    //初始化矩阵
    void  initlinks()
    {
        int count;
        for (int j = 0; j < n; j++)
        {
            count = 0;
            for (int i = 0; i < n; i++)
            {
                if (links[i][j])
                {
                    count++;
                }
            }

            if (count > 1)
            {
                for (int i = 0; i < n; i++)
                {
                    if (links[i][j])
                    {
                        links[i][j] = 1.0 / count;
                    }
                }
            }
        }
        Teleport();
    }

    // 迭代计算PR值
    void calcPR() {

        initPR();
        initlinks();

        vector<double> newPR(n, 0);
        while (true) {
            double diff = 0;
            for (int j = 0; j < n; ++j) {
                newPR[j] = 0;

                // 计算(1 - beta) / n * sum(PR[i])
                double sum = 0;
                for (int i = 0; i < n; ++i) {
                    sum += PR[i] / n;
                }
                sum *= 1 - beta;

                // 计算beta * PR[i]*(经过Teleport处理的M矩阵)
                double tmp = 0;
                for (int i = 0; i < n; ++i) {
                    tmp += PR[i] * links[j][i];
                }
                tmp *= beta;

                // 计算PR[j]
                newPR[j] = sum + tmp;

                diff += fabs(newPR[j] - PR[j]); // 计算PR值的变化
            }

            PR = newPR; // 更新PR值

            if (diff < epsilon) { // 如果变化小于精度，则结束迭代
                break;
            }
        }
    }

public:
    PageRank(int n, double beta, double epsilon) : n(n), beta(beta), epsilon(epsilon) {
        links.resize(n, vector<double>(n, 0));
        PR.resize(n, 0);
        zeroOutLinks.resize(n, false);
    }

    // 手动添加网页链接
    void addLink(int from, int to) {
        if (to < 0 || to >= n || from < 0 || from >= n)
        {
            cout << "...error..." << endl;
            return;
        }
        links[to][from] = 1;
    }

    //自动添加网页链接
    void RandomLink()
    {
        for (int i = 0; i < n; i++)
        {
            for(int j=0;j<n;j++)
            {
                if (rand() % 2)
                {
                    links[i][j] = 1;
                }
            }
        }
    }

    //获取最终的PR值
    void getPR()
    {
        calcPR();
        for (int i = 0; i < n; i++)
        {
            cout << "PR[" << i << "] = " << PR[i] << endl;
        }
    }
};

void main() {
    srand((unsigned)time(NULL));
    PageRank pr(3, 0.85, 1e-6);

    pr.addLink(0, 0);
    pr.addLink(1, 0);
    pr.addLink(1, 2);
    pr.addLink(2, 0);
    pr.addLink(2, 1);

    pr.getPR();
