#include <iostream>
#include <string>
#include <vector>

using namespace std;

string encrypt(string plaintext, vector<int> key1, vector<int> key2)
{
    int rows = key1.size();
    int cols = (plaintext.length() + rows - 1) / rows; // округление в большую сторону

    // создаем двумерный массив и заполняем его пробелами
    vector<vector<char>> table(rows, vector<char>(cols, ' '));

    // записываем символы исходного текста в таблицу по строкам
    int index = 0;
    for (int i = 0; i < cols; i++)
    {
        for (int j = 0; j < rows; j++)
        {
            if (index >= plaintext.length()) break;
            table[key1[j]-1][i] = plaintext[index];
            index++;
        }
    }

    // считываем зашифрованный текст по столбцам и формируем строку
    string ciphertext;
    for (int i = 0; i < cols; i++)
    {
        int col_index = key2[i]-1;
        for (int j = 0; j < rows; j++)
        {
            if (table[j][col_index] != ' ') 
            {
                ciphertext += table[j][col_index];
            }
        }
    }

    return ciphertext;
}

