    std::vector<int> data = {5, 3, 8, 1, 7, 2, 9};

    // Create a BST using the modified Selection Sort
    BST bst;
    bstFromSelectionSort(data, bst);

    // Output the data in the BST using inorder traversal
    bst.inorderTraversal();

